type Env = {
    DB: D1Database;
};

type PlaceRow = {
    id: string;
    name: string;
    slug: string;
    short_description: string | null;
    category_id: string | null;
    area: string | null;
    city: string | null;
    price_min: number | null;
    price_max: number | null;
    price_range: string | null;
    image_url: string | null;
    is_featured: number;
    is_active: number;
    created_at: string;
    updated_at: string;
    category_name: string | null;
    category_slug: string | null;
};

type TagRow = {
    place_id: string;
    id: string;
    name: string;
    slug: string;
    type: string;
};

type CompactTag = {
    id: string;
    name: string;
    slug: string;
    type: string;
};

type ApiResponse = {
    success: boolean;
    data?: unknown;
    message?: string;
};

export const onRequestGet: PagesFunction<Env> = async (context) => {
    try {
        const url = new URL(context.request.url);

        const search = url.searchParams.get("search")?.trim() ?? "";
        const featured = url.searchParams.get("featured");
        const rawLimit = Number(url.searchParams.get("limit") ?? "100");

        const safeLimit = Math.min(
            Number.isFinite(rawLimit) && rawLimit > 0 ? rawLimit : 100,
            100
        );

        const conditions: string[] = ["p.is_active = 1"];
        const params: unknown[] = [];

        if (search) {
            conditions.push(
                `(
          p.name LIKE ?
          OR p.short_description LIKE ?
          OR p.area LIKE ?
          OR p.city LIKE ?
          OR c.name LIKE ?
        )`
            );

            const keyword = `%${search}%`;
            params.push(keyword, keyword, keyword, keyword, keyword);
        }

        if (featured === "true") {
            conditions.push("p.is_featured = 1");
        }

        const placesQuery = `
      SELECT
        p.id,
        p.name,
        p.slug,
        p.short_description,
        p.category_id,
        p.area,
        p.city,
        p.price_min,
        p.price_max,
        p.price_range,
        p.image_url,
        p.is_featured,
        p.is_active,
        p.created_at,
        p.updated_at,
        c.name AS category_name,
        c.slug AS category_slug
      FROM places p
      LEFT JOIN categories c ON c.id = p.category_id
      WHERE ${conditions.join(" AND ")}
      ORDER BY p.is_featured DESC, p.created_at DESC
      LIMIT ?
    `;

        params.push(safeLimit);

        const placesResult = await context.env.DB
            .prepare(placesQuery)
            .bind(...params)
            .all<PlaceRow>();

        const places = placesResult.results ?? [];

        if (places.length === 0) {
            return publicJson({
                success: true,
                data: [],
            });
        }

        const placeIds = places.map((place) => place.id);
        const tagsByPlaceId = await getTagsByPlaceId(context.env.DB, placeIds);

        const data = places.map((place) => {
            const tags = tagsByPlaceId.get(place.id) ?? [];

            return {
                id: place.id,
                name: place.name,
                slug: place.slug,

                short_description: compactText(place.short_description, 180),

                category_id: place.category_id,
                area: place.area,
                city: place.city,

                price_min: place.price_min,
                price_max: place.price_max,
                price_range: place.price_range,

                image_url: place.image_url,

                is_featured: Boolean(place.is_featured),
                is_active: Boolean(place.is_active),
                is_published: Boolean(place.is_active),

                created_at: place.created_at,
                updated_at: place.updated_at,

                categories: place.category_id
                    ? {
                        id: place.category_id,
                        name: place.category_name,
                        slug: place.category_slug,
                    }
                    : null,

                tags,
            };
        });

        return publicJson({
            success: true,
            data,
        });
    } catch (error) {
        console.error("GET /api/places error:", error);

        return errorJson(
            {
                success: false,
                message: "Failed to fetch places",
            },
            500
        );
    }
};

export const onRequestHead: PagesFunction<Env> = async () => {
    return new Response(null, {
        status: 200,
        headers: getPublicCacheHeaders(),
    });
};

async function getTagsByPlaceId(db: D1Database, placeIds: string[]) {
    const tagsByPlaceId = new Map<string, CompactTag[]>();

    if (placeIds.length === 0) {
        return tagsByPlaceId;
    }

    const placeholders = placeIds.map(() => "?").join(",");

    const tagsResult = await db
        .prepare(
            `
      SELECT
        pt.place_id,
        t.id,
        t.name,
        t.slug,
        t.type
      FROM place_tags pt
      INNER JOIN tags t ON t.id = pt.tag_id
      WHERE pt.place_id IN (${placeholders})
      ORDER BY t.type ASC, t.name ASC
    `
        )
        .bind(...placeIds)
        .all<TagRow>();

    for (const tag of tagsResult.results ?? []) {
        const currentTags = tagsByPlaceId.get(tag.place_id) ?? [];

        currentTags.push({
            id: tag.id,
            name: tag.name,
            slug: tag.slug,
            type: tag.type,
        });

        tagsByPlaceId.set(tag.place_id, currentTags);
    }

    return tagsByPlaceId;
}

function compactText(value: string | null, maxLength: number) {
    const text = String(value ?? "").trim();

    if (text.length <= maxLength) {
        return text || null;
    }

    return `${text.slice(0, maxLength).trim()}...`;
}

function getPublicCacheHeaders() {
    return {
        "Cache-Control":
            "public, max-age=60, s-maxage=300, stale-while-revalidate=86400",
        "CDN-Cache-Control": "public, max-age=300",
        "Cloudflare-CDN-Cache-Control": "public, max-age=300",
        "X-Saranwak-Api-Version": "places-lite-v3",
    };
}

function publicJson(body: ApiResponse, status = 200) {
    return Response.json(body, {
        status,
        headers: getPublicCacheHeaders(),
    });
}

function errorJson(body: ApiResponse, status = 500) {
    return Response.json(body, {
        status,
        headers: {
            "Cache-Control": "no-store",
            "X-Saranwak-Api-Version": "places-lite-v3-error",
        },
    });
}